function [modelComparison, sensitivity] = run_young_sensitivity(outputDirectory)
%RUN_YOUNG_SENSITIVITY Observational conditional-modulus audit, not a gate.
% Truth is the independent forward CSV generated by Python. This workflow
% only evaluates the production inverse under true and perturbed inputs.
% Call MATLAB with -singleCompThread for repeatable bounded local execution.
    if nargin<1, outputDirectory=fileparts(mfilename('fullpath')); end
    workflowRoot=fileparts(fileparts(fileparts(outputDirectory)));
    run(fullfile(workflowRoot,'startup.m'));
    reference=readtable(fullfile(outputDirectory,'forward_reference_cases.csv'), ...
        'TextType','string');
    comparisons={}; perturbations={};
    for index=1:height(reference)
        c=reference(index,:);
        correct=string(c.reference_model);
        options=struct('model',correct,'density_kg_m3',c.true_density_kg_m3, ...
            'poisson_ratio',c.true_poisson_ratio,'thickness_m',c.true_thickness_m, ...
            'frequency_hz',c.frequency_hz,'max_kh',0.6);
        if correct=="lamb_a0_free", models=["lamb_a0_free","lamb_a0_thin","rayleigh"];
        elseif correct=="rayleigh", models=["rayleigh","bulk_shear"];
        else, models=["bulk_shear","rayleigh"]; end
        for model=models
            selected=options; selected.model=model;
            comparisons{end+1,1}=evaluate(c,selected,c.truth_phase_speed_m_s, ...
                "model_choice",NaN); %#ok<AGROW>
        end
        % One-at-a-time perturbations quantify conditional sensitivity;
        % they are not estimates of actual experimental uncertainty.
        for factor=[0.90 0.95 1.05 1.10]
            perturbations{end+1,1}=evaluate(c,options,c.truth_phase_speed_m_s*factor, ...
                "speed_factor",factor); %#ok<AGROW>
            perturbed=options; perturbed.density_kg_m3=options.density_kg_m3*factor;
            perturbations{end+1,1}=evaluate(c,perturbed,c.truth_phase_speed_m_s, ...
                "density_factor",factor); %#ok<AGROW>
            if correct=="lamb_a0_free"
                perturbed=options; perturbed.thickness_m=options.thickness_m*factor;
                perturbations{end+1,1}=evaluate(c,perturbed,c.truth_phase_speed_m_s, ...
                    "thickness_factor",factor); %#ok<AGROW>
            end
        end
        for delta=[-0.03 -0.01 0.01 0.03]
            perturbed=options; perturbed.poisson_ratio=options.poisson_ratio+delta;
            % Values >=0.5 remain explicit rejected rows. Never clip an
            % invalid elastic assumption to obtain an accepted result.
            perturbations{end+1,1}=evaluate(c,perturbed,c.truth_phase_speed_m_s, ...
                "poisson_delta",delta); %#ok<AGROW>
        end
    end
    modelComparison=struct2table(vertcat(comparisons{:}));
    sensitivity=struct2table(vertcat(perturbations{:}));
    writetable(modelComparison,fullfile(outputDirectory,'young_model_comparison.csv'));
    writetable(sensitivity,fullfile(outputDirectory,'young_input_sensitivity.csv'));
    save(fullfile(outputDirectory,'young_sensitivity_products.mat'), ...
        'reference','modelComparison','sensitivity');
    fprintf('Young model rows: %d; perturbation rows: %d\n', ...
        height(modelComparison),height(sensitivity));
    fprintf('Exact correct-model max relative error: %.9g %%\n', ...
        max(abs(modelComparison.relative_error_pct(modelComparison.selected_model==modelComparison.reference_model)),[],'omitnan'));
    a0thin=modelComparison.reference_model=="lamb_a0_free" & modelComparison.selected_model=="lamb_a0_thin";
    fprintf('A0 thin gate accepted %d of %d; max accepted error %.9g %%\n', ...
        nnz(modelComparison.accepted(a0thin)),nnz(a0thin), ...
        max(abs(modelComparison.relative_error_pct(a0thin & modelComparison.accepted)),[],'omitnan'));
end

function row=evaluate(c,options,speed,perturbation,value)
    row=struct('case_id',c.case_id,'reference_model',c.reference_model, ...
        'selected_model',string(options.model),'true_E_pa',c.true_E_pa, ...
        'true_density_kg_m3',c.true_density_kg_m3, ...
        'true_poisson_ratio',c.true_poisson_ratio,'true_thickness_m',c.true_thickness_m, ...
        'frequency_hz',c.frequency_hz,'truth_phase_speed_m_s',c.truth_phase_speed_m_s, ...
        'truth_kh',c.truth_kh,'assumed_speed_m_s',speed, ...
        'assumed_density_kg_m3',options.density_kg_m3, ...
        'assumed_poisson_ratio',options.poisson_ratio, ...
        'assumed_thickness_m',options.thickness_m,'perturbation',string(perturbation), ...
        'perturbation_value',value,'young_pa',NaN,'relative_error_pct',NaN, ...
        'accepted',false,'kh_inferred',NaN,'a0_asymptotic_used',false, ...
        'status',"",'exception_id',"");
    try
        product=oce.elastography.invertYoungModulus(speed,options);
        row.accepted=product.valid_mask;
        row.young_pa=product.young_pa;
        row.kh_inferred=product.diagnostics.kh;
        row.a0_asymptotic_used=product.diagnostics.a0_small_kh_asymptotic_used;
        if row.accepted
            row.relative_error_pct=100*(row.young_pa/c.true_E_pa-1);
            row.status="accepted";
        else, row.status="model_gate_rejected"; end
    catch exception
        row.status="invalid_input_or_solver_rejected";
        row.exception_id=string(exception.identifier);
    end
end
